(1,'User Mail Send','user_mail','User',NULL,'Official Notification','[[subject]]','Hello [[full_name]]','[[message]]',NULL,NULL,1,'FrontField Credit Union',0,'What is [[site_title]]','[[site_title]]','[\"[[full_name]]\",\"[[site_url]]\",\"[[site_title]]\",\"[[subject]]\",\"[[message]]\"]',1,NULL,'2026-02-23 16:27:34'),
(2,'Subscriber Mail Send','subscriber_mail','Subscriber',NULL,'Welcome to [[site_title]]','[[subject]] for [[full_name]]','Hi [[full_name]]','[[message]]<br><br>Find out more at [[site_url]]',NULL,NULL,1,'Thanks for joining our platform!',0,'What is [[site_title]]','[[site_title]]','[\"[[site_url]]\",\"[[site_title]]\",\"[[subject]]\",\"[[message]]\"]',1,NULL,'2026-02-23 16:27:34'),
(3,'Email Verification','email_verification','User',NULL,'Email Verification Required','Verify Your Email Address - FrontField Credit Union','Hello [[full_name]]','Welcome to FrontField Credit Union. To ensure the security of your account and activate your full digital banking features, please verify your email address. This step helps us protect your sensitive financial information.','Verify My Email','[[token]]',1,'Secure Banking, Simplified.',0,'Verify Email Address','If you\'re having trouble clicking the \"Verify Email Address\" button, copy and paste the URL below into your web browser:[[token]]','[\"[[token]]\",\"[[full_name]]\",\"[[site_title]]\",\"[[site_url]]\"]',1,NULL,'2026-02-23 16:27:34'),
(4,'Forget Password','user_password_change','User',NULL,'Security: Password Update','Password Reset Request','Hello [[full_name]]','We received a request to reset your digital banking password. To choose a new secure password, please click the button below. If you did not make this request, your account is still secure and you can safely ignore this email.','Set New Password','[[token]]',1,'Your Security is Our Priority.',0,'User Password Change','[[token]]','[\"[[token]]\",\"[[site_title]]\",\"[[site_url]]\"]',1,NULL,'2026-02-23 16:27:34'),
(6,'User Account Disabled','user_account_disabled','User',NULL,'Account Status Update','Important: Account Security Notification','Dear [[full_name]]','For your security and the protection of your assets, your digital banking access has been temporarily deactivated. This often occurs due to extended inactivity or for account verification purposes.<br><br>To restore your access, please contact our member support team or attempt to securely verify your identity through our portal.','Contact Support','[[site_url]]/contact',1,'Integrity in Every Transaction.',0,'User Account Disabled','[[full_name]]','[\"[[full_name]]\",\"[[site_title]]\",\"[[site_url]]\"]',1,NULL,'2026-02-23 16:27:34'),
(7,'Manual Deposit request','manual_deposit_request','Admin',NULL,'Manual Deposit request','Got a request for Manual Deposit','Hi Admin','The manual deposit request details:<br />[[txn]]<br />[[gateway_name]]<br />[[deposit_amount]]',NULL,NULL,1,'Regards, [[site_title]]',0,'Manual Deposit request','[[site_title]]','[\"[[full_name]]\",\"[[txn]]\",\"[[gateway_name]]\",\"[[deposit_amount]]\",\"[[site_title]]\",\"[[site_url]]\"]',1,NULL,'2026-02-23 16:27:34'),
(8,'Withdraw Request (Admin)','withdraw_request ','Admin',NULL,'Withdraw Request','Got a Withdraw Request','Hi Admin','Withdraw Request details:<br />[[txn]]<br />[[method_name]]<br />[[withdraw_amount]]',NULL,NULL,1,'Regards, [[site_title]]',0,'Withdraw Request','[[full_name]]','[\"[[full_name]]\",\"[[txn]]\",\"[[method_name]]\",\"[[withdraw_amount]]\",\"[[site_title]]\",\"[[site_url]]\"]',1,NULL,'2026-02-23 16:27:34'),
(9,'Admin Forget Password','admin_forget_password','Admin',NULL,'Admin Forget Password','Admin Forget Password','Hi Admin','Please click the button below to reset your password','Password reset','[[token]]',1,'Regards, [[site_title]]',0,'Withdraw Request','[[full_name]]   <br />\r\n[[token]]','[\"[[token]]\",\"[[site_title]]\",\"[[site_url]]\"]',1,NULL,'2026-02-23 16:27:34'),
(10,'Contact Mail Send','contact_mail','Admin',NULL,'Inquiry from [[full_name]]','[[subject]] for [[full_name]]','Hi Admin','[[message]]<br><hr>Sender: [[full_name]] ([[email]])',NULL,NULL,1,'Inquiry recorded via [[site_url]]',0,'What is [[site_title]]','[[site_title]]','[\"[[site_url]]\",\"[[site_title]]\",\"[[full_name]]\",\"[[email]]\",\"[[subject]]\",\"[[message]]\"]',1,NULL,'2026-02-23 16:27:34'),
(11,'KYC Request','kyc_request','Admin',NULL,'KYC Review Required','KYC Verification Request - [[full_name]]','Hi Admin','A user has submitted KYC documents for review.<br><br>User: [[full_name]]<br>Email: [[email]]<br>Type: [[kyc_type]]',NULL,NULL,1,'Compliance Management System',0,'What is [[site_title]]','[[site_title]]','[\"[[site_url]]\",\"[[site_title]]\",\"[[full_name]]\",\"[[email]]\",\"[[kyc_type]]\"]',1,NULL,'2026-02-23 16:27:34'),
(12,'KYC Action','kyc_action','User',NULL,'KYC / Proof of Identity','Identity Verification Update','Hi [[full_name]]','Your identity verification documents (KYC) have been reviewed. The current status of your verification is: <strong>[[status]]</strong>.<br><br>[[message]]','View Verification Status','[[site_url]]/user/kyc',1,'Complying with Federal Regulations for Your Safety.',0,'What is [[site_title]]','[[site_title]]','[\"[[site_url]]\",\"[[site_title]]\",\"[[full_name]]\",\"[[email]]\",\"[[message]]\",\"[[kyc_type]]\"]',1,NULL,'2026-02-23 16:27:34'),
(15,'Withdraw Request Action','withdraw_request_user','User',NULL,'Account Activity: Withdrawal','Withdrawal Notification: [[status]]','Dear [[full_name]]','This email is to inform you of a status update regarding your withdrawal request. Your request is currently: <strong>[[status]]</strong>.<br><br><strong>Transaction Details:</strong><br>Transaction ID: [[txn]]<br>Amount: [[withdraw_amount]]<br>Method: [[method_name]]<br><br>[[message]]','Review Transaction','[[site_url]]/user/withdraw/history',1,'Committed to Your Financial Success.',0,'Withdraw Request','[[full_name]]','[\"[[full_name]]\",\"[[message]]\",\"[[txn]]\",\"[[method_name]]\",\"[[withdraw_amount]]\",\"[[site_title]]\",\"[[site_url]]\",\"[[status]]\"]',1,NULL,'2026-02-23 16:27:34'),
(16,'Manual Deposit request Action','user_manual_deposit_request','User',NULL,'Account Activity: Deposit','Deposit Notification: [[status]]','Hello [[full_name]]','We are writing to update you on your recent deposit request to <strong>[[to_account]]</strong>. The transaction status is currently: <strong>[[status]]</strong>.<br><br><strong>Transaction Details:</strong><br>ID: [[txn]]<br>Transaction Type: [[gateway_name]]<br>Amount: [[deposit_amount]]<br><br>[[message]]','View My Account','[[site_url]]/user/deposits/history',1,'Supporting Your Financial Growth.',0,'Manual Deposit request','[[full_name]]','[\"[[full_name]]\",\"[[message]]\",\"[[txn]]\",\"[[gateway_name]]\",\"[[deposit_amount]]\",\"[[site_title]]\",\"[[site_url]]\",\"[[status]]\"]',1,NULL,'2026-03-19 05:13:43'),
(17,'Support Ticket Update','user_support_ticket','User',NULL,'Support Request Update','Update: Support Ticket [[title]]','Hello [[full_name]]','We have an update regarding your support ticket: <strong>[[title]]</strong>.<br><br><strong>Current Status:</strong> [[status]]<br><br><strong>Message:</strong><br>[[message]]','View Support Ticket','[[site_url]]/user/support-ticket',1,'We Are Here to Assist You.',0,'Support Ticket','[[full_name]]','[\"[[full_name]]\",\"[[title]]\",\"[[message]]\",\"[[site_title]]\",\"[[site_url]]\",\"[[status]]\"]',1,NULL,'2026-02-23 16:27:34'),
(18,'Support Ticket (Admin)','admin_support_ticket','Admin',NULL,'Support Ticket','Support Ticket Update','Hi Admin','Support Ticket:<br />[[title]]<br />[[message]]<br />Status: [[status]]',NULL,NULL,1,'Member Support System',0,'Support Ticket','[[full_name]]','[\"[[full_name]]\",\"[[title]]\",\"[[message]]\",\"[[site_title]]\",\"[[site_url]]\",\"[[status]]\"]',1,NULL,'2026-02-23 16:27:34'),
(29,'Internal Fund Transfer Request','fund_transfer_request','User',NULL,'Transfer Confirmation','Fund Transfer Confirmation: [[amount]]','Hi [[full_name]]','Your request to transfer <strong>[[amount]]</strong> from <strong>[[from_account]]</strong> to <strong>[[to_account]]</strong> has been received and is being processed.<br><br><strong>Transaction Details:</strong><br>Reference ID: <strong>[[tnx]]</strong><br>From Account: [[from_account]]<br>To Account: [[to_account]]<br>Amount: [[amount]]<br>Fee: [[charge]]<br>Total Debited: [[total_amount]]<br>Status: [[status]]<br>Initiated at: [[date]]<br>Memo: [[memo]]','View Activity','[[site_url]]/user/dashboard',1,'Thank you for banking with FrontField Credit Union.',0,NULL,'[[site_title]]','[\"[[full_name]]\",\"[[status]]\",\"[[charge]]\",\"[[account_number]]\",\"[[account_name]]\",\"[[branch_name]]\",\"[[amount]]\",\"[[total_amount]]\"]',1,'2024-04-23 00:15:59','2026-03-19 05:13:43'),
(30,'Wire Transfer Request','wire_transfer_request','User',NULL,'Processing Request','Wire Transfer Notification: [[status]]','Hi [[full_name]]','We have received your wire transfer request for [[amount]]. The transaction is currently [[status]].',NULL,NULL,1,'Global Banking, Local Care.',0,NULL,'[[site_title]]','[\"[[full_name]]\",\"[[status]]\",\"[[charge]]\",\"[[account_number]]\",\"[[name_of_account]]\",\"[[swift_code]]\",\"[[phone_number]]\",\"[[amount]]\",\"[[total_amount]]\"]',1,'2024-04-23 00:15:59','2026-02-23 16:27:34'),
(31,'DPS Closed','dps_closed','User',NULL,'Account Update: [[plan_name]] Activity','Savings Plan Notification','Hi [[full_name]]','There has been activity on your [[plan_name]] account. <br><br><strong>Details:</strong><br>Plan: [[plan_name]]<br>ID: [[dps_id]]<br>Status/Action: [[status]]<br>Matured Amount/Balance: [[matured_amount]]',NULL,NULL,1,'Helping you save for what matters.',0,NULL,'[[site_title]]','[\"[[plan_name]]\",\"[[dps_id]]\",\"[[per_installment]]\",\"[[interest_rate]]\",\"[[installment_date]]\",\"[[delay_charge]]\",\"[[given_installment]]\",\"[[total_installment]]\",\"[[matured_amount]]\"]',1,'2024-04-23 00:15:59','2026-02-23 16:27:34'),
(32,'DPS Installment Due','dps_installment_due','User',NULL,'Savings Account Notification','Savings Alert: Installment Due','Hi [[full_name]]','Your installment for [[plan_name]] savings plan is now due. Ensuring consistent contributions helps you reach your financial goals faster.',NULL,NULL,1,'Secure Growth. Guaranteed.',0,NULL,'[[site_title]]','[\"[[plan_name]]\",\"[[dps_id]]\",\"[[per_installment]]\",\"[[interest_rate]]\",\"[[installment_date]]\",\"[[delay_charge]]\",\"[[given_installment]]\",\"[[total_installment]]\",\"[[matured_amount]]\"]',1,'2024-04-23 00:15:59','2026-02-23 16:27:34'),
(33,'DPS Completed','dps_completed','User',NULL,'Savings Account Activity','Savings Plan Notification: [[status]]','Hello [[full_name]]','We have an update regarding your <strong>[[plan_name]]</strong> savings plan. Activity has been recorded with the status: <strong>[[status]]</strong>.<br><br><strong>Activity Details:</strong><br>Plan Type: [[plan_name]]<br>Matured Amount/Balance: [[matured_amount]]<br><br>Check your dashboard for comprehensive savings history.','View Savings','[[site_url]]/user/dps/list',1,'Building Your Future, One Step at a Time.',0,NULL,'[[site_title]]','[\"[[plan_name]]\",\"[[dps_id]]\",\"[[per_installment]]\",\"[[interest_rate]]\",\"[[installment_date]]\",\"[[delay_charge]]\",\"[[given_installment]]\",\"[[total_installment]]\",\"[[matured_amount]]\"]',1,'2024-04-23 00:15:59','2026-02-23 16:27:34'),
(34,'FDR Closed','fdr_closed','User',NULL,'FDR Status Change','FDR Account Closed','Hello [[full_name]]','Your FDR plan <strong>[[plan_name]]</strong> (#[[fdr_id]]) has been closed upon request. Refunds have been processed as per the plan terms.',NULL,NULL,1,'Always Here to Help.',0,NULL,'[[site_title]]','[\"[[plan_name]]\",\"[[fdr_id]]\",\"[[amount]]\",\"[[interest_rate]]\",\"[[given_installment]]\",\"[[installment_interval]]\",\"[[next_installment_date]]\",\"[[total_installment]]\"]',1,'2024-04-23 00:15:59','2026-02-23 16:27:34'),
(35,'FDR Completed','fdr_completed','User',NULL,'FDR Account Matured','FDR Maturity Notification','Dear [[full_name]]','Your FDR plan <strong>[[plan_name]]</strong> has reached maturity. The principal and final interest have been successfully settled to your primary account balance.',NULL,NULL,1,'Thank You for Investing with Us.',0,NULL,'[[site_title]]','[\"[[plan_name]]\",\"[[fdr_id]]\",\"[[amount]]\",\"[[interest_rate]]\",\"[[given_installment]]\",\"[[installment_interval]]\",\"[[next_installment_date]]\",\"[[total_installment]]\"]',1,'2024-04-23 00:15:59','2026-02-23 16:27:34'),
(36,'FDR Installment','fdr_installment','User',NULL,'FDR Account Activity','FDR Interest Credited','Hi [[full_name]]','Interest for your FDR plan <strong>[[plan_name]]</strong> has been credited to your account balance.<br><br><strong>Details:</strong><br>Interest Credited: [[per_installment]]<br>Next Interest Date: [[next_installment_date]]',NULL,NULL,1,'Your Capital, Our Responsibility.',0,NULL,'[[site_title]]','[\"[[plan_name]]\",\"[[fdr_id]]\",\"[[amount]]\",\"[[interest_rate]]\",\"[[given_installment]]\",\"[[installment_interval]]\",\"[[next_installment_date]]\",\"[[total_installment]]\"]',1,'2024-04-23 00:15:59','2026-02-23 16:27:34'),
(37,'Loan Approved','loan_approved','User',NULL,'Lending Decision Notification','Loan Application Status: [[status]]','Dear [[full_name]]','We are pleased to provide an update on your [[plan_name]] loan application. Your application has been updated to: <strong>[[status]]</strong>.<br><br><strong>Summary:</strong><br>Loan Amount: [[loan_amount]]<br>Installment Rate: [[installment_rate]]<br><br>Please log in to your dashboard to review the terms or complete any pending actions.','Review Loan Terms','[[site_url]]/user/loan/list',1,'Empowering Your Dreams.',0,NULL,'[[site_title]]','[\"[[plan_name]]\",\"[[loan_id]]\",\"[[installment_rate]]\",\"[[loan_amount]]\",\"[[given_installment]]\",\"[[installment_interval]]\",\"[[next_installment_date]]\",\"[[total_installment]]\"]',1,'2024-04-23 00:15:59','2026-02-23 16:27:34'),
(38,'Loan Rejected','loan_rejected','User',NULL,'Lending Update','Loan Application Update - [[plan_name]]','Dear [[full_name]]','Your loan application status for the [[plan_name]] plan has been updated to <strong>[[status]]</strong>. <br><br>Amount: [[loan_amount]]<br><br>Please log in to your account for more information.',NULL,NULL,1,'Investing in your dreams.',0,NULL,'[[site_title]]','[\"[[plan_name]]\",\"[[loan_id]]\",\"[[installment_rate]]\",\"[[loan_amount]]\",\"[[installment_interval]]\"]',1,'2024-04-23 00:15:59','2026-02-23 16:27:34'),
(39,'Loan Installment','loan_installment','User',NULL,'Lending Account Activity','Loan Installment Processed','Hello [[full_name]]','Your loan installment for [[plan_name]] (#[[loan_id]]) has been processed.<br><br><strong>Transaction Details:</strong><br>Amount: [[installment_amount]]<br>Next Installment: [[next_installment_date]]',NULL,NULL,1,'Partnering in Your Financial Journey.',0,NULL,'[[site_title]]','[\"[[plan_name]]\",\"[[loan_id]]\",\"[[installment_rate]]\",\"[[loan_amount]]\",\"[[delay_charge]]\",\"[[installment_amount]]\",\"[[given_installment]]\",\"[[installment_interval]]\",\"[[next_installment_date]]\",\"[[total_installment]]\"]',1,'2024-04-23 00:15:59','2026-02-23 16:27:34'),
(40,'Loan Installment Due','loan_installment_due','User',NULL,'Urgent: Lending Account Alert','Action Required: Loan Installment Due','Dear [[full_name]]','A payment for your loan [[plan_name]] (#[[loan_id]]) is currently overdue or requires attention. Please ensure sufficient funds are available for processing.<br><br><strong>Details:</strong><br>Amount: [[installment_amount]]<br>Total Due: [[loan_amount]]',NULL,NULL,1,'Member Security & Success.',0,NULL,'[[site_title]]','[\"[[plan_name]]\",\"[[loan_id]]\",\"[[loan_amount]]\",\"[[installment_rate]]\",\"[[delay_charge]]\",\"[[installment_amount]]\",\"[[given_installment]]\",\"[[installment_interval]]\",\"[[next_installment_date]]\",\"[[total_installment]]\"]',1,'2024-04-23 00:15:59','2026-02-23 16:27:34'),
(41,'Portfolio Achieve','portfolio_achieve','User',NULL,'Membership Recognition','Congratulations: Portfolio Milestone Achieved','Dear [[full_name]]','Congratulations! You have achieved the <strong>[[portfolio_name]]</strong> status. This milestone reflects your continued trust and activity with FrontField Credit Union. We have applied your membership rewards to your account balance.',NULL,NULL,1,'Excellence in Membership.',0,NULL,'[[site_title]]','[\"[[portfolio_name]]\"]',1,'2024-04-23 00:15:59','2026-02-23 16:27:34'),
(42,'Get Rewards','get_rewards','User',NULL,'You Got Points!','Congratulations! Rewards Earned','Hi [[full_name]]','Great news! You have just earned <strong>[[points]]</strong> reward points for your recent activity. Thank you for being an active member of FrontField Credit Union.',NULL,NULL,1,'More rewards, more reasons to bank with us.',0,NULL,'[[site_title]]','[\"[[points]]\"]',1,'2024-04-23 00:15:59','2026-02-23 16:27:34'),
(43,'Generic OTP','otp','User',NULL,'Identity Verification','Your Security Code: [[otp_code]]','Hello [[full_name]]','For your security, we require a verification code to authorize the following action: <strong>[[action]]</strong>.<br><br><div style=\"text-align:center; font-size: 32px; font-weight: bold; color: #00549b; letter-spacing: 5px; padding: 20px; background: #f8fafc; border-radius: 8px; margin: 20px 0;\">[[otp_code]]</div><br>This code is valid for a single use only. If you did not initiate this request, please contact our security team immediately.',NULL,NULL,1,'FrontField Credit Union Security Team',0,NULL,NULL,NULL,1,'2026-02-21 14:47:05','2026-02-23 16:27:34'),
(44,'MFA Generic OTP','mfa_otp','User',NULL,'Security Authorization','Authorization Code: [[otp_code]]','Dear [[full_name]]','To complete your requested action (<strong>[[action]]</strong>), please enter the authorization code provided below:<br><br><div style=\"text-align:center; font-size: 32px; font-weight: bold; color: #00549b; letter-spacing: 5px; padding: 20px; background: #f8fafc; border-radius: 8px; margin: 20px 0;\">[[otp_code]]</div><br>This code will expire in 10 minutes. <strong>FrontField Credit Union will never ask for this code over the phone or via text.</strong>',NULL,NULL,1,'Always Secure. Always FrontField.',0,NULL,NULL,NULL,1,'2026-02-21 14:47:05','2026-02-23 16:27:34'),
(45,'MFA Transfer Verification','mfa_transfer','User',NULL,'Transfer Authorization','Verify Your Fund Transfer - [[otp_code]]','Hi [[full_name]]','You are initiating a fund transfer. Please enter the following authorization code to confirm this transaction:<br><br><div style=\"text-align:center; font-size: 32px; font-weight: bold; color: #00549b; letter-spacing: 5px; padding: 20px; background: #f8fafc; border-radius: 8px; margin: 20px 0;\">[[otp_code]]</div><br>If this was not you, please log in to your account and change your security settings immediately.','Secure My Account','[[site_url]]/user/settings/security',1,'FrontField Credit Union Member Support',0,NULL,NULL,NULL,1,'2026-02-21 14:47:05','2026-02-23 16:27:34'),
(46,'MFA Withdrawal Verification','mfa_withdrawal','User',NULL,'Withdrawal Authorization','Confirm Your Withdrawal Request - [[otp_code]]','Dear [[full_name]]','We received a request to withdraw funds from your account. To ensure this request is authorized, please provide the following security code:<br><br><div style=\"text-align:center; font-size: 32px; font-weight: bold; color: #da291c; letter-spacing: 5px; padding: 20px; background: #fff5f5; border-radius: 8px; margin: 20px 0;\">[[otp_code]]</div><br>This extra step helps us keep your hard-earned money safe.',NULL,NULL,1,'FrontField Credit Union | Your Security is Our Priority',0,NULL,NULL,NULL,1,'2026-02-21 14:47:05','2026-02-23 16:27:34'),
(47,'MFA Profile Update','mfa_profile_update','User',NULL,'Security: Profile Update','Verify Profile Change - [[otp_code]]','Hello [[full_name]]','A change has been requested to your sensitive profile information (such as your email or username). Please use the code below to verify this change:<br><br><div style=\"text-align:center; font-size: 32px; font-weight: bold; color: #00549b; letter-spacing: 5px; padding: 20px; background: #f8fafc; border-radius: 8px; margin: 20px 0;\">[[otp_code]]</div><br>If you did not request this change, please secure your account immediately.','Change Password','[[site_url]]/user/settings/security',1,'Helping you grow and protect your wealth.',0,NULL,NULL,NULL,1,'2026-02-21 14:47:05','2026-02-23 16:27:34'),
(48,'MFA Security Change','mfa_security_change','User',NULL,'Authorization Required','Authorize Security Setting Change - [[otp_code]]','Hi [[full_name]]','You are updating your security settings (Password or PIN). To confirm this action, please enter the following code:<br><br><div style=\"text-align:center; font-size: 32px; font-weight: bold; color: #00549b; letter-spacing: 5px; padding: 20px; background: #f8fafc; border-radius: 8px; margin: 20px 0;\">[[otp_code]]</div><br>Stay safe and secure.',NULL,NULL,1,'Team FrontField Credit Union',0,NULL,NULL,NULL,1,'2026-02-21 14:47:05','2026-02-23 16:27:34'),
(49,'Own Bank Transfer','fund_transfer','User',NULL,'Transfer Processed','Transfer Success: [[amount]]','Hi [[full_name]]','Great news! Your internal transfer has been processed successfully.<br><br><strong>Transaction Summary:</strong><br>From: [[from_account]]<br>To: [[to_account]]<br>Amount: [[amount]]<br>Deducted: [[total_amount]]<br>Ref: [[txn]]',NULL,NULL,1,'Secure. Simple. FrontField.',0,'','',NULL,1,'2026-02-23 15:49:28','2026-03-19 05:13:43'),
(50,'Wire Transfer (Result)','wire_transfer','User',NULL,'Wire Transfer Notification','Wire Transfer Status: [[status]]','Hi [[full_name]]','We are writing to inform you that your wire transfer to <strong>[[account_number]]</strong> has been processed. Status: <strong>[[status]]</strong>.<br><br><strong>Summary:</strong><br>Amount: [[amount]]<br>Fee: [[charge]]<br>Total: [[total_amount]]',NULL,NULL,1,'Global Banking, Local Care.',0,'','',NULL,1,'2026-02-23 15:49:28','2026-02-23 16:27:34'),
(51,'DPS Opened','dps_opened','User',NULL,'Savings Account Created','DPS Savings Plan Opened - [[plan_name]]','Dear [[full_name]]','You have successfully opened a <strong>[[plan_name]]</strong> DPS savings plan (#[[dps_id]]).<br><br><strong>Summary:</strong><br>Installment: [[per_installment]]<br>Interest Rate: [[interest_rate]]%<br>Total Installments: [[total_installment]]',NULL,NULL,1,'Saving for a brighter tomorrow.',0,'','',NULL,1,'2026-02-23 15:49:28','2026-02-23 16:27:34'),
(52,'FDR Opened','fdr_opened','User',NULL,'FDR Account Created','FDR Subscription Successful','Dear [[full_name]]','You have successfully subscribed to the <strong>[[plan_name]]</strong> FDR plan.<br><br><strong>Summary:</strong><br>Principal: [[amount]]<br>Interest Rate: [[interest_rate]]%<br>Term: [[installment_interval]] Days',NULL,NULL,1,'Integrity. Transparency. Growth.',0,'','',NULL,1,'2026-02-23 15:49:28','2026-02-23 16:27:34'),
(53,'Loan Application (Admin)','loan_apply','Admin',NULL,'Lending Alert','New Loan Application Received','Hi Admin','A new loan application has been submitted.<br><br>User: [[full_name]]<br>Plan: [[plan_name]]<br>Amount: [[loan_amount]]',NULL,NULL,1,'Lending Management System',0,'','',NULL,1,'2026-02-23 15:49:28','2026-02-23 16:27:34'),
(129,'Member Transfer Approved','member_transfer_approved','User',NULL,'Transfer Completed','Member Transfer Completed: [[to_account]]','Hi [[full_name]]','Great news! Your member(M2M) transfer of <strong>[[amount]]</strong> has been completely processed and credited To: <strong>[[to_account]]</strong>.<br><br><strong>Transaction Summary:</strong><br>From: [[from_account]]<br>To: [[to_account]]<br>Amount: [[amount]]<br>Fee: [[charge]]<br>Total Deducted: [[total_amount]]<br>Memo: [[memo]]<br><br>Time/Date: [[date]]',NULL,NULL,1,'Reliable. Secure. FrontField.',1,NULL,NULL,NULL,1,NULL,'2026-03-19 05:13:43'),
(130,'Member Transfer Cancelled','member_transfer_rejected','User',NULL,'Transfer Notice','Transfer Update: Member Transfer to [[to_account]] Cancelled.','Hi [[full_name]]','We were unable to process your transfer of <strong>[[amount]]</strong> to <strong>[[to_account]]</strong>.<br><br><strong>Details:</strong><br>From: [[from_account]]<br>Reason: [[message]]<br><br>The funds (including fees) have been returned to your account.',NULL,NULL,1,'Questions? We are here to help.',1,NULL,NULL,NULL,1,NULL,'2026-03-19 05:13:43'),
(131,'External Transfer Completed','external_transfer_approved','User',NULL,'External Transfer Completed','External Transfer Completed: [[amount]]','Hi [[full_name]]','Your external transfer request has been successfully processed.<br><br><strong>TRANSACTION DETAILS</strong><br>From:<strong> [[from_account]] </strong><br>To:<strong> [[to_account]] </strong><br>Bank: [[bank_name]]<br>Amount: [[amount]]<br>Fee: [[charge]]<br>Total: [[total_amount]]<br>Time/Date: [[date]]',NULL,NULL,1,'Thank you for choosing FrontField Credit Union.',1,NULL,NULL,NULL,1,NULL,'2026-03-19 05:13:43'),
(132,'External Transfer Cancelled','external_transfer_rejected','User',NULL,'External Transfer Update','External Transfer Cancelled','Hi [[full_name]]','Your external transfer request to <strong>[[to_account]]</strong> could not be completed.<br><br><strong>Status:</strong> Cancelled<br><strong>Reason:</strong> [[message]]<br><br>Funds have been returned to your [[from_account]] account.<br>Contact support for more information. ',NULL,NULL,1,'Please contact us for more information.',1,NULL,NULL,NULL,1,NULL,'2026-03-19 05:13:43'),
(133,'Remote Deposit Approved','remote_deposit_approved','User',NULL,'Check Deposit Success','Remote Deposit Credit: [[check_amount]]','Hi [[full_name]]','Your remote check deposit for <strong>[[check_amount]]</strong> has been cleared and credited to your <strong>[[to_account]]</strong>.<br><br><strong>Details:</strong><br>Capture Date: [[capture_date]]<br>Credit Date: [[date]]<br>Amount: [[check_amount]]',NULL,NULL,1,'Safe. Secure. Remote Banking.',1,NULL,NULL,NULL,1,NULL,'2026-03-19 05:13:43'),
(134,'Remote Deposit Returned','remote_deposit_rejected','User',NULL,'Check Deposit Notice','Remote Deposit Update: Check Returned','Hi [[full_name]]','We were unable to process your remote check deposit of <strong>[[check_amount]]</strong>.<br><br><strong>Reason:</strong> [[note]]<br>Time/Date: [[date]]<br><br>Please note that a returned check fee may apply. Contact support for further details.',NULL,NULL,1,'Always Here to Help.',1,NULL,NULL,NULL,1,NULL,'2026-03-19 05:13:43'),
(144,'Admin Fund Transfer Alert','admin_fund_transfer_notification','Admin',NULL,'Transfer Oversight Alert','ALERT: New [[transfer_type]] - [[amount]] ([[risk_level]])','Hi Admin,','A new fund transfer requires your review.<br><br><strong>User:</strong> [[full_name]]<br><strong>Amount:</strong> [[total_amount]]<br><strong>Type:</strong> [[transfer_type]]<br><strong>From:</strong> [[from_account]]<br><strong>To:</strong> [[to_account]]<br><br><div style=\"padding:15px; background:#fff5f5; border-radius:8px; border:1px solid #feb2b2;\"><strong>Risk Assessment:</strong> [[risk_score]]/100<br><strong>Flags:</strong> [[risk_flags]]</div>','Review Transfer','[[site_url]]/admin/fund-transfer/pending',1,'FrontField Credit Union Administrative Oversight',0,NULL,NULL,NULL,1,'2026-03-20 10:48:11','2026-03-20 10:48:11'),
(145,'Admin: New Member Transfer Submitted','admin_member_transfer_submitted','User',NULL,'New Member Transfer Awaiting Review','Action Required: New Member Transfer from [[full_name]]','Hello Admin,','A new member transfer has been submitted and requires your review.\n\nMember: [[full_name]]\nAmount: [[amount]]\nFrom Account: [[from_account]]\nTo: [[to_account]]\nMemo: [[memo]]\nDate: [[date]]\n\nPlease log in to the admin portal to review and approve or reject this transfer.','Review Transfer','[[review_url]]',1,'This is an automated notification from [[site_title]].',0,'','',NULL,1,'2026-03-20 15:06:44','2026-03-20 15:06:44'),
(146,'Admin: New External Transfer Submitted','admin_external_transfer_submitted','User',NULL,'New External Transfer Awaiting Review','Action Required: New External Transfer from [[full_name]]','Hello Admin,','A new external transfer has been submitted.\n\nMember: [[full_name]]\nAmount: [[amount]]\nTo Bank: [[bank_name]]\nRouting #: [[routing_number]]\nAccount #: [[recipient_account]]\nMemo: [[memo]]\nDate: [[date]]\n\nPlease log in to the admin panel to review this transfer.','Review Transfer','[[review_url]]',1,'This is an automated notification from [[site_title]].',0,'','',NULL,1,'2026-03-20 15:06:44','2026-03-20 15:06:44'),
(148,'Remote Deposit Submitted','remote_deposit_submitted','User',NULL,'Check Received','Check Deposit Received - [[site_title]]','Hello [[full_name]],','<p>We have received your mobile check deposit of [[amount]] to your [[account_name]].</p>\r\n<div style=\"background: #f8f9fa; padding: 15px; border-radius: 8px; margin: 20px 0;\">\r\n<h4 style=\"margin-top: 0; color: #00549b;\">Deposit Details</h4>\r\n<table style=\"width: 100%; border-collapse: collapse;\">\r\n<tr><td style=\"padding: 5px 0; color: #666;\">Amount:</td><td style=\"padding: 5px 0; font-weight: bold; text-align: right; color: #28a745;\">[[amount]]</td></tr>\r\n<tr><td style=\"padding: 5px 0; color: #666;\">Account:</td><td style=\"padding: 5px 0; font-weight: bold; text-align: right;\">[[account_name]] ([[account_number]])</td></tr>\r\n<tr><td style=\"padding: 5px 0; color: #666;\">Transaction ID:</td><td style=\"padding: 5px 0; font-weight: bold; text-align: right;\">[[txn]]</td></tr>\r\n<tr><td style=\"padding: 5px 0; color: #666;\">Status:</td><td style=\"padding: 5px 0; font-weight: bold; text-align: right; color: #ffc107;\">Pending Review</td></tr>\r\n</table>\r\n</div>\r\n<p>Our team is now reviewing the deposit. You will receive another notification once it is processed and completed or if more information is needed.</p>',NULL,NULL,1,NULL,1,NULL,NULL,NULL,1,'2026-03-21 17:23:03','2026-03-21 17:23:03'),
(149,'Card Status Update','card_status_update','User',NULL,'Card Update','Security Alert: Card Status Changed','Hello [[full_name]],','<p>A status change was detected for your card ending in [[card_number]].</p>\r\n<div style=\"background: #f8f9fa; padding: 15px; border-radius: 8px; margin: 20px 0;\">\r\n<h4 style=\"margin-top: 0; color: #00549b;\">Update Details</h4>\r\n<table style=\"width: 100%; border-collapse: collapse;\">\r\n<tr><td style=\"padding: 5px 0; color: #666;\">Card Number:</td><td style=\"padding: 5px 0; font-weight: bold; text-align: right;\">[[card_number]]</td></tr>\r\n<tr><td style=\"padding: 5px 0; color: #666;\">New Status:</td><td style=\"padding: 5px 0; font-weight: bold; text-align: right;\">[[status]]</td></tr>\r\n</table>\r\n</div>\r\n<p>[[message]]</p>\r\n<p style=\"color: #666; font-size: 13px;\">If you did not authorize this change, please contact support immediately.</p>',NULL,NULL,1,NULL,1,NULL,NULL,NULL,1,'2026-03-21 17:23:03','2026-03-21 17:23:03'),
(150,'Card Security Update','card_security_update','User',NULL,'Security Update','Security Alert: Card Security Action','Hello [[full_name]],','<p>A security action was performed on your card ending in [[card_number]].</p>\r\n<div style=\"background: #f8f9fa; padding: 15px; border-radius: 8px; margin: 20px 0;\">\r\n<h4 style=\"margin-top: 0; color: #00549b;\">Action Details</h4>\r\n<table style=\"width: 100%; border-collapse: collapse;\">\r\n<tr><td style=\"padding: 5px 0; color: #666;\">Card Number:</td><td style=\"padding: 5px 0; font-weight: bold; text-align: right;\">[[card_number]]</td></tr>\r\n<tr><td style=\"padding: 5px 0; color: #666;\">Action:</td><td style=\"padding: 5px 0; font-weight: bold; text-align: right;\">[[action]]</td></tr>\r\n</table>\r\n</div>\r\n<p>[[message]]</p>\r\n<p style=\"color: #666; font-size: 13px;\">If you did not authorize this action, please contact support immediately.</p>',NULL,NULL,1,NULL,1,NULL,NULL,NULL,1,'2026-03-21 17:23:03','2026-03-21 17:23:03');
